SELECT

FROM backup_record
WHERE deleted = 1

    AND backup_type = #{backupType,jdbcType=TINYINT}


    AND status = #{status,jdbcType=TINYINT}


    AND create_time >= #{startTime,jdbcType=TIMESTAMP}


    AND create_time <= #{endTime,jdbcType=TIMESTAMP}

ORDER BY create_time DESC

