    update_time = NOW()

        , file_size = #{fileSize,jdbcType=BIGINT}


        , duration_ms = #{durationMs,jdbcType=BIGINT}


        , error_message = #{errorMessage,jdbcType=LONGVARCHAR}

WHERE id = #{id,jdbcType=BIGINT} AND deleted = 1

